  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (145::BIGINT, 'Hace el curso muy sencillo, dejó varias clases virtuales y se trabaja bastante en grupo. Es importante la asistencia.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'c39020278d92e7bae806131c736c6a942d5e1c078c11a48fcf1b00ad9682630e'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Muy linda persona, sus clases son rapidas y siempre salimos mas temprano. Relativamente facil, mucho trabajo en parejas + el proyecto final en grupo. Se pasa muy facil, pero solamente que sus clases son MUY aburridas y redundantes.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-17T00:00:00+00:00'::TIMESTAMPTZ, '68872367700de97daa90bc8ef2fe87d8430ecb3cb7d8070a6ccb6a5c15facb60'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'La profesora es un sol, pero en verdad el curso le consume a uno mucho tiempo. La recomendaria full'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'a733fd28de579845f6839dc92c561f42d58c54c5dcb7949886aacf979b908eaa'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'la profe es buena gente, deja trabajos todas las clases, algunas veces se vuelve un poco hablantina y hace la clase pesada pero esta bien'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, '4cda5d3787ebc0ad28f68a05584dff04f4690d4046261690a5b932774bfb4c98'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Hace el curso muy facil, la asistencia es obligatoria y las evaluaciones son muy fáciles, recomendada. Siempre termina la clase antes.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-12-01T00:00:00+00:00'::TIMESTAMPTZ, '6bd2b1c18c55e0c8f16c28d8cfb1b52e68789f38e29221eba8491659604e7c57'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '2daf94e6a8adc2b4faab12e0c705402d4ed2ac6d7c4cc8bcaafab459bfdd12d9'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Excelente profe y persona, se pasa con 100 facilmente. Deja algunas tareas pero son faciles y sacando el ratito se hacen facil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2022-12-07T00:00:00+00:00'::TIMESTAMPTZ, '989723877ea37174249a3997c081f629a7fe1dead41099af6b171b4c09bf187a'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Es muy buena persona, le preocupa los estudiantes y escucha sus peticiones. Las presentaciones a veces me aburrían y deja trabajos todas las clases. Los trabajos son sencillos, pero el informe si es poco más largo y como es grupal a veces es molesto, pero ella resuelve cada problema que surja.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-15T00:00:00+00:00'::TIMESTAMPTZ, '5c8a040649d850a60dc47636b9fac19ad2b9eb5a10389b71ad41a94c9f954886'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Muy buena profe, siempre resuelve sus dudas pero si es un poquito estricta a la hora de calificar. Es solo de pponer atención en clase y pasan!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2020-07-17T00:00:00+00:00'::TIMESTAMPTZ, '86f38df3a4b077086c9b0cf4eefea44493f44c83b2feadd3da353b53d4692562'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Matricule con ella, qué espera?!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-07-01T00:00:00+00:00'::TIMESTAMPTZ, '9971003cabf3636c404540d651ffbbf342cc88775917bb5699ef934cc9a7800e'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Muy buena profesora, explica bien, deja muchos trabajos, no hay exámenes pero muchos trabajos escritos y muchas presentaciones, pero califica suave y siempre ayuda a los estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '0bf9a64f4c7296c659976dc3da7d3cd0d6c29c05c6524d89e53ae2a4e7138bba'::TEXT, ARRAY[556]::BIGINT[]),
    (145::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-30T00:00:00+00:00'::TIMESTAMPTZ, '793cfbbcc03518933d59aab8db09ad8fab88d0e5e89d190866259b9047df0823'::TEXT, ARRAY[556]::BIGINT[]),
    (145::BIGINT, 'Sus clases son super aburridas, casi no deja exposiciones, es super facil el curso pero hay profes mejores'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-28T00:00:00+00:00'::TIMESTAMPTZ, '2a6f4b209e5169e9fcf4772b1f2c792b38697e120740a3c2b30973f9c5dee5d0'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'La profesora muy buena gente y cariñosa. Por cierto es muy linda. Las clases son muy buenas y con solo hacer bien todos los trabajos pasa, se aprende mucho. A pesar que soy sordo me apoyó mucho y me preguntaba que sí entendió o no, me explicaba otra vez. Muy recomendado.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, '9157c45a8e1bf88e42b8aa2e3adf00be52364823350d5b63c27a54585d403fc6'::TEXT, ARRAY[556]::BIGINT[]),
    (145::BIGINT, 'Excelente profesora, super comprensiva y amable. Explica bien los temas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2017-01-23T00:00:00+00:00'::TIMESTAMPTZ, '4a628b24e84873f8a4fbf3d61b8d47430cd39287e1d15a139e416828bd3058b1'::TEXT, ARRAY[600, 554]::BIGINT[]),
    (145::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, '90cd75911d85f259b112fffbc6769a20e11685b4d9c5bc04ed58d3bd91aeb50c'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'e65bb4f0ad7121e9b3bb9e55c306dbb20d1e386e5374dd2560d283ca1554633b'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-23T00:00:00+00:00'::TIMESTAMPTZ, '0e926d3235b9cd1b2aed895027a04b1437f900cd82806d013623c52affbd6d2a'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Buena profe, amable y explica bien (Y)'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-28T00:00:00+00:00'::TIMESTAMPTZ, 'a5752710bd2f21b62a03027367023f13b7689838ad091cad89f4c5136f796518'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Se aprende lo suficiente, excelente persona, no le quitará tiempo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'fe3a72700a98b6c227324c0490a46a81e5e53ac85a76970ca08dceb71afbc5d2'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Es demasiado buena gente y es fácil pasar el curso con ella y a la vez aprendiendo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-13T00:00:00+00:00'::TIMESTAMPTZ, 'feded8122c8d9527dfde437c6d69d09dcd323cc5934542e922e81171031c9154'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-23T00:00:00+00:00'::TIMESTAMPTZ, '6619e77128d2bb819f629b9dfc954a8062f1df51fe3b43422235fd32f182b452'::TEXT, ARRAY[556]::BIGINT[]),
    (145::BIGINT, 'es un amor. no se aprende tanto como con otros profes pero si lo suficiente. trabajos super faciles, califica muuuy suave, un curso con ella nunca quitará tiempo. bastante rejalada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'dcde3d0cbc1b96c89e36f03833ad956aa87bef7da232ad381aabc4a31b13df6d'::TEXT, ARRAY[556]::BIGINT[]),
    (145::BIGINT, 'Esta profe es un amor y es super fácil pasar con ella'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '9b50b4e1ae7787267b7c00f416451732e3405a7885324ecd24dbe7a468a727c7'::TEXT, ARRAY[556]::BIGINT[]),
    (145::BIGINT, 'Súper fácil sacarse una buena nota. Las clases son cortas, manda indicaciones puntuales. Clase rápida. Nota que saqué: 100'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2026-07-04T00:00:00+00:00'::TIMESTAMPTZ, 'b0ccf6ff195067c9dd30fb0fd6cc4a021dcf9b62dbddec57725b7ac734a8357c'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Ella es un amor de profesora, matriculen con ella, es muy servicial, explica muy bien y para los proyectos ella te va guiando y revisando que tengas todo claro. Le gusta realizar bastantes trabajos en grupo, pero son cortos y normalmente son parte de lo que viene a ser el trabajo final.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-28T00:00:00+00:00'::TIMESTAMPTZ, '8ae95ca4bb824d2df9ee7f70d374c06d8207024fffbd9847f50e79ed2caf17e3'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Es una profesora que deja el curso bastante fácil, ya que toma dos clases para las presentaciones, una de práctica y la otra para calificar. Es comprensiva y amable.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2025-08-11T00:00:00+00:00'::TIMESTAMPTZ, 'cb21b4441df9c3f844fc4a20e19dfd91adc9b96015aa7b6199fe7352bc192ba8'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Es una gran profesora,pero aveces sus explicaciones no son lo bastante claras y uno queda con ciertas dudas, pero califica bastante suave y te pone a trabajar y uno aprende a base de los trabajos'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-08T00:00:00+00:00'::TIMESTAMPTZ, '0300fc2f0eb1be54eb13582a1aa7ceb5f865e36a445a9ab7de9532473274ff89'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Hace el curso muy sencillo, dejó varias clases virtuales y se trabaja bastante en grupo. Es importante la asistencia.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'c5ddfbb6567539a7f6071cd7141d8d805572f417e857bb5f76106cc4aff868e1'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'La profe es increíble, súper recomendada. Su forma de tratar a los estudiantes es muy buena.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2024-12-27T00:00:00+00:00'::TIMESTAMPTZ, '7e03426390442db22fc0eaecd7efff7bb5534cd46bb49b9e13ee08eaaec34ceb'::TEXT, ARRAY[600, 554]::BIGINT[]),
    (145::BIGINT, 'Muchos trabajos y presentaciones, es buena persona, el curso se pasa sencillo, pero supongo que hay mejores profesores.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2024-11-25T00:00:00+00:00'::TIMESTAMPTZ, '0a8c6a9bc3a94958d3bebf0e8b8aa67ea9cdc4781f1071593186e1092e8836ec'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Es buena profesora, califica de forma justa según su desempeño. El curso se pasa fácil si usted entrega todos los trabajos y se prepara para las presentaciones.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2024-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'eb1b8025d62a75a86ef048a40c47dce8b7540c182698091a3c4ca688e72d0668'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Forma de calificar muy arbitraria. A veces se pasa de cuestionable.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'c2da4c52b2071a14c984836c7c1c07e4f156a566878a2ceeaf6d79f13af876f8'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Muy buena profe tanto para oral como escrita, califica depende como usted se muestre al hacer las presentaciones orales. No hay otra mejor opción que ella.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'cef019e44d6cfbdd19b5f9171429486e581c002bcee4e4f0cc101c94c5ffaded'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Muy buena profesora, llegá a calificar medio duro pero si evalua justo. La verdad súper buena profesora y persona.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2024-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'a9d3e226764143a35b90357b3a58d72a73d327e53c22c78af90303a439478c57'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Es super fría. Me parece que las exposiciones las califica según como usted le cae, compañeros con desempeño parecido a mí tenían calificaciones más altas. Repite las cosas, es super aburrido. dentro de los profes de la escuela puede que sea de los mejores, aunque realmente no sea tan buena.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2024-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'b0ade5604585b0eb8d5bde15510223eb16838f58096b3f3077a52f611f4c1535'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Muy buena profesora, no obstante debe poner atención en clase, llegar temprano por que es estricta con las ausencias y tardías y entregar los trabajos a tiempo, si hace todo esto pasa muy fácil. Tampoco califica duro'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2024-06-11T00:00:00+00:00'::TIMESTAMPTZ, '43b25e33dfd2b3630e3f4355306a6931d548bd48aaaeb120688878f9c4da94fe'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Muy buena profe, muy amable y comprensiva pero hay una presentación medio larga individual al final del curso.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'cfaf57e310a47380a0e06424c913779707f6e5036fb32616fbcb45c02dfd4c26'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'La clase realmente es aburrida, pero ella trata de hacer que no se vuelva pesada. No va a aprender tanto como debería, pero eso es más culpa de la estructura del curso que de la profe en sí. Da bastante retroalimentación. Definitivamente recomendada.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Clase fácil', 'Brinda apoyo']::TEXT[], '2023-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'ea3a8f63ecfe18bacb452cc8c130a4875395994dd81040becb2fa406969fdb28'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Las clases son entretenidas y cumple muy bien el objetivo del curso, es una prode excelente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo']::TEXT[], '2023-07-13T00:00:00+00:00'::TIMESTAMPTZ, 'd719721fdc4a999a4a2b545b48b78544600be86f485746d0ba98c4d6335c4ce1'::TEXT, ARRAY[698]::BIGINT[]),
    (145::BIGINT, 'Deja pocas tareas y se pasa muy relajado con ella. Es muy buena persona.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'e1dc4b3c5b5cee5014fca979012e0a4cda6bf45160997cd745591ffedef9c388'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'El curso en sí es muy fácil, pero ella lo hace aun más fácil, casi no deja tareas y mientras usted cumpla con lo que pide ese curso lo pasa con 100 cerrado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2023-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'ac239645b06b4ac1849d50f6c4d1f9e49423361e9cb46d425cbd480fac5df316'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Muy buena profe, muy gentil y el curso se pasa facilísimo, yo no preparé casi ninguna exposición y ella regala la teja'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-12T00:00:00+00:00'::TIMESTAMPTZ, '7a27e81a1ada54726944243ee95ac0b02b81af6194856fc92cda54677bee58aa'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Excelente profe y persona, se pasa con 100 facilmente. Deja algunas tareas pero son faciles y sacando el ratito se hacen facil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2022-12-07T00:00:00+00:00'::TIMESTAMPTZ, '989723877ea37174249a3997c081f629a7fe1dead41099af6b171b4c09bf187a'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Súper entretenida la clase'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'ebc6d3354d2dada83bc266a8692b92a9aec2cab1e01b187d1e2d1e6c4c3c9721'::TEXT, ARRAY[698]::BIGINT[]),
    (145::BIGINT, 'Deja bastantes tareas pero por lo general son tareas cortas, las clases también son cortas y llevaderas. En términos generales, el curso con ella es bastante fácil.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2022-05-31T00:00:00+00:00'::TIMESTAMPTZ, '82d4de246bc0d2b170abccfb9542760cf949aa70c61e8bf92979459b3cc537d0'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Es una profe increible, super buena nota, super comprensible y además de eso sabe dar muy bien sus clases, deja mucho trabajo en clase eso sí, pero la verdad es bueno porque evita que te deje tareas. la verdad recomiendo mucho llevar con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-04-06T00:00:00+00:00'::TIMESTAMPTZ, '3036c9bc61bff1d3ca7363caaa5de8fe868f7d99779fdf4b2f532310da9dfc89'::TEXT, ARRAY[556]::BIGINT[]),
    (145::BIGINT, 'Es una excelente profesora, yo lo lleve en verano y no es duro llevarlo con ella apesar de que se tienen que entregar trabajos cortos el mismo dia de la sesion.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2022-01-20T00:00:00+00:00'::TIMESTAMPTZ, '10a947344a121d5713e0b598c4441f03f6502a14330daac137ddf355a9e9a318'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'La profesora es muy buena gente, da clases sincrónicas normalmente un día por semana, los trabajos no son dificiles pero si de cuidado ya que revisa todo y califica duro errores ortograficos o de estructura según el trabajo, brinda ayuda normalmente solo en consulta'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2022-01-01T00:00:00+00:00'::TIMESTAMPTZ, 'faab7bf91a36f90495fcc6534996bea0df11e211139916bacdafbed0779e5ff4'::TEXT, ARRAY[556]::BIGINT[]),
    (145::BIGINT, 'La profesora es muy amigable, sin embargo en sus clases solo lee documentos que perfectamente el estudiante podría haber leído por su cuenta y obtener el mismo aprendizaje, pero sus trabajos son bastante sencillos comparados a otros profesores de este curso y se asegura de dar apoyo en los trabajos.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'fe298f7f3bf54d17e1486eb81d2a71ddf809c1a678de66d13efab90826736748'::TEXT, ARRAY[556]::BIGINT[]),
    (145::BIGINT, 'La profe es un amor, la forma y la organización del curso es excelente! Califica muy suave pero deja muchos trabajos grupales. Ayuda bastante. Deja carpetas en el tecDigital entonces no confundirse cuando se sube algo. Pasa lista.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2021-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'daaa41d634c0d6ae60a8f63d256c66919c68c50e77219ba4052111dfe786ca5c'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Es un amor, las clases son amenas (aunque un poco aburridas) y califica bastante suave, es muy sencillo pasar si se llevan todas las tareas al día.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '790f0496408f6ecf71b95475e3d69ef3f03010fc680dd92a889729b2f9d6693e'::TEXT, ARRAY[556]::BIGINT[]),
    (145::BIGINT, 'La profe es súper cariñosa, pasar es sencillo, califica un poco rudo cuando se trata de ortografía y gramática, pero nada de que preocuparse. Es muy tranquila, explica muy bien. Da buenas retroalimentaciones y resuelve dudas de manera muy clara. Súper recomendada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, '7c7e3ae067c7c82abd487aa856e312d09bbf59a69482d053c22a0792df19941f'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Excelente profesora, siempre explica claro. Califica bastante suave y genera un ambiente de confianza. Los trabajos tienen instrucciones claras. Las notas las da hasta el final.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, '13d924662562ddb3a164362c93e8e55066839081c063ef371d9b24529c5a60e3'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Muy buena profe. Deja un par de tareas semanales pero son bastante sencillas y nada del otro mundo. Explica muy bien y deja en claro las rubricas de evaluacion. 100% recomendada!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '24cf9741e46dee6959d0b141cff239d09ad5356849149835e72022726bd21388'::TEXT, ARRAY[556]::BIGINT[]),
    (145::BIGINT, 'Demasiado buena. Con ella todo es muy claro: la forma de evaluar y la materia. Las clases no son aburridas, hace chistes y se conversa. Las evaluaciones que hace no son nada del otro mundo y califica suave; entonces, se pasa fácil y se aprende bastante. No dude en matricular con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Brinda apoyo']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '8d31ee1a5aba299ee0b67b2f73fe9dbfd611abc60e799a64896813b2d29758cd'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Ella es un amor de persona, agrada conversar con ella y tomar su clase. Deja tareas súper sencillas al igual que sus clases; todo lo hace bastante práctico. La recomiendo 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-05T00:00:00+00:00'::TIMESTAMPTZ, '752989e80e29d87ffe1f34db21739070baa403fadcdc53e449438c193b181cd0'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'El curso es muy sencillo con esta profe. Explica muy claro tanto los aspectos de calificación como la materia y hace lo posible por ayudarlo para que le vaya bien. Si hace todos los trabajos le va a ir bien. Tenga cuidado cuando suba las tareas en el Tec Digital, procure no equivocarse de carpeta.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '74ae940fca7f26836b97b0e09666ff9b6d6a10b44ad36b58c70d602ce25d55cd'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Está hecha de amor. Siempre está dispuesta a ayudar. Instrucciones muy claras. Hiso el curso muy ameno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, '13ff0eb0e49e7d2e43e054f229f72f5e959fd61701d9edcf497fd59b03f0d71c'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Con ella es muy fácil de pasar. Si tiene la opción de matricular con ella, hágalo, no lo dude. Es una excelente profe.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-19T00:00:00+00:00'::TIMESTAMPTZ, 'beb26b0a5f95fa9fa8d151da3e19b33aa24c1c7e9641146e97d9a1a3005fa50b'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Para la materia, es una profe Excelente, no dude en matricular con ella, deja tareas pero nada fuera de lo normal. Le interesa que uno entienda bien y que aprenda.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '5d224b1a426cf9f0527477f01b0bbb6a84a2f5e5d4748419acd0b9ba83b8b01d'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Una excelente profesora, es muy comprensiva con el alumno, deja bastante claro como desea los trabajos 10/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '685f098bdbed30ed64c77ae99af098c7a6a7f61261e122fc8ba032cbead51630'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Es super buena profe, y es muy fácil. Se aprende de verdad.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, '032c8763a9f182f721281ce0421beaa53e8d7464b615eb0b5ed37f6747b28b65'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'La profe es súper linda persona, en la clase explica como hacer TODO de la mejor manera y si ocupas ayuda ella siempre lo hace con mucho gusto. Califica suave y te corrige lo que hiciste mal sin bajarte demasiado. El curso se pasa súper fácil y aprendes bastante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '1bc9e162daa42b73e050b33b1ce975a045f81821ce7f9a137a06798cfc3b9c2e'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Las clases son un poco largas porque explica a detalle cómo hacer las cosas bien con el informe y el ensayo. Revias suave, pero realiza críticas constructivas para que uno sepa cuáles son sus errores sin perjudicarle la nota.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases largas']::TEXT[], '2020-08-07T00:00:00+00:00'::TIMESTAMPTZ, 'd7f74799e98850e2bdf887577d67862e4a770e819882b20c10c7669c1b3d4934'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'La profe aveces se pone a vacilar con nosotros, es un poco aburrida y la clase también pero se pasa fácil, eso sí acepto que evalúa muy cómodo para el estudiante porque no califica duro y de verdad da criticas constructivas de como mejorar sus debilidades por eso es muy respetada, exc profe por eso.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2020-01-15T00:00:00+00:00'::TIMESTAMPTZ, 'f3f4febd5ce1c8c0a088dd8a1fa109e6f3dda5210b113350167cf266b92a7fb7'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-12-18T00:00:00+00:00'::TIMESTAMPTZ, 'd54a281a2d3a0fed30e7782d4fb7eae916f8046c92f9a12742f314aef0201a3d'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Súper buena profe. La mejor de la escuela diría yo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, '1b8d6fae9be7d5778303ace1c6841dc257e36605cc9034fa65a5606c0fdc5b16'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Si quiere pasar Comu relajado, matricule con ella'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'e158179e0aba23c12d902cc45ec88730a3195c6e7e99be70e9b47ad1f6b7c781'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'La clase es aburrida. Si terminás el trabajo rápido te podés ir temprano. Nunca le entendí lo que explicaba, pero siempre subía las indicaciones de cada trabajo a tecDigital y esos documentos sí se entienden mejor. No regala la nota pero tampoco califica duro.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-07-15T00:00:00+00:00'::TIMESTAMPTZ, '519d611a1699ab860b7a7603c2d3ce46b44a01cbff6a9dcbbf5703aa8b727d1e'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Todo se hace en clases, los trabajos son sencillos pero hay que ponerle en clases porque sino todo se le acumula para la casa. Se pasa muy fácil. Deja salir temprano. Curso fácilmente ganado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'fc919f1a497cbc36fe654b4706c71cb3419682014e7d25a1cc2ba47a3b6764c9'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Súper buena profe. Todos los trabajos se desarrollan en clase así que no demanda tiempo extra. Presente todo completo y listo, de fijo obtiene una nota de 90 o más. Si está pensando en matricular con ella no lo dude.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'a7b45857143acf9b24e46502f0d3f69e9ab19a6668930b0b8b4e45b89cbf3282'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Una profesora genial, dirige la materia donde tiene que sin dar muchas vueltas. Asegúrese de estar al tanto de la entrega de los trabajos y eso es todo, créditos aprobados gratis.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '5e21bb33440dc00387afdefdf0eb03095ebde3d0494ebe6d0bb12413a0dbdd68'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Es buena, nunca supe qué era lo que iba a calificar en un trabajo hasta que me lo entregaba, pero todas las clases se puede ir a trabajar afuera y no califica duro'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'e3ce4f20360a35eecc93948deca5e084d384b370f5cace1a9ca3be75ad91e4bf'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'A la hora de calificar es medio carepinguilla, pero es muy buena nota.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'd55062119c2317b9fa13c09151c00fb11eb7626b30381657f25d0b6cfd27ee59'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Una profe muy buena, los trabajos grandes (propuesta, informe técnico, texto académico) esté llevándolos a revisión antes de la entrega final, y ella le ayuda un montón para corregirlos. Súper recomendada'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-15T00:00:00+00:00'::TIMESTAMPTZ, '815d5f9737f9f41a26c044709838aca9b0b9a2c9f48b3d61feb17a4a7a43a7a2'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Simplemente la mejor, básicamente todo lo del curso se hace en clase, ayuda montones, las clases casi siempre terminan mucho antes, si puede lleve con ella, 10/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'cc325e39c3203ac60308e89f1b35538bc2767edb64214fdb4126a69fff23a7c7'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Excelente profe, explica bien, ayuda mucho y hace el curso bastante ligero y sustancioso, las clases son un poco cansadas pero suelen se entretenidas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2019-06-11T00:00:00+00:00'::TIMESTAMPTZ, '228fd23429570db68b457efeed2d2288cc339c3423a0c5dac8fa72c67b7c2530'::TEXT, ARRAY[556]::BIGINT[]),
    (145::BIGINT, 'No califica duro, con que trabaje en clase todo bien. Es una buena opción para llevar Comu'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2019-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'c23a0f2e59603a5d5aadc17d8809f77cceb84bfdbda3fadfb84c490cf282cc46'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Se pasa super fácil el curso, si quiere subir el ponderado llevelo con ella y haga todos los trabajos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'e84c7439ec306e3084813a0587ec2d42f39e57d337f8d8882a054201ff668067'::TEXT, ARRAY[556]::BIGINT[]),
    (145::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'bff2409599d7490be04d25250de8f99e8fe2a164796f0df78a24af0b6a6c14ff'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Muy buena profe. El curso se hace sencillo y entretenido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2018-11-09T00:00:00+00:00'::TIMESTAMPTZ, '4f8e2695c34e24d68b23b64febac931e206b5029e314a3caea4c00e6f2c10c38'::TEXT, ARRAY[556]::BIGINT[]),
    (145::BIGINT, 'Es muy buena profesora, ayuda mucho si tienes dudas con algo ella te las aclara, le interesa que los estudiantes realmente aprendan, a pesar de que ella deja muchos trabajos califica con suavidad'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-28T00:00:00+00:00'::TIMESTAMPTZ, '960d6b89251e0f5b368a8d36a229813be176eb3065a37552960c7b27c8bb8837'::TEXT, ARRAY[556]::BIGINT[]),
    (145::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '724ad0e9dce6783f109a86a27dcc9b80429614ad386f5bc4cf4ad66ccedc9f2e'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Ella es buena persona pero se enoja si no le hacen caso. Deja solo dos trabajos grandes, pero es llevadero. Las clases muchas veces consisten en estar sentado haciendo nada, PERO, deja salir temprano. Explica bien y las clases no son taaaan aburridas. Recomendada.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'f27a0e2fe525da79254d9a6acce3209765500f89b3d63e6d0889e2f816bf65c2'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Muy buena profesora, explica bien, deja muchos trabajos, no hay exámenes pero muchos trabajos escritos y muchas presentaciones, pero califica suave y siempre ayuda a los estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'afd57d520ca8fc33468fd363aa69edade5913808e7b8d92371f56bc213884277'::TEXT, ARRAY[556]::BIGINT[]),
    (145::BIGINT, 'Muy buena y comprensiva. Las clases no son aburridas y es muy amigable. Solo hay que tener cuidado con los trabajos porque no sabes nada de tu nota hasta el puro final. Brinda mucha ayuda en la clase pero por correo, olvídalo. Super recomendada'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'f39f0c3936ef3a4158af28c3aad41526eb4ad24781bc84bdd7890d67fb1f0ec4'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'La mejor opción'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'd6bfa390a8eeff79ec8273f851e1079d918e04a99304a0686c6be72d62a878c6'::TEXT, ARRAY[556]::BIGINT[]),
    (145::BIGINT, 'Extremadamente buena, sin importar el curso matricule con ella, va a costar mucho que haya alguien mejor que ella'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-02T00:00:00+00:00'::TIMESTAMPTZ, '54eb7bb48f501d9b6d9b4ecf50e327cab3045e4d1840ca9da78284a187ecc8fe'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Es muy buena'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-30T00:00:00+00:00'::TIMESTAMPTZ, '1c0075b0a4d5fd4b61699f366cd97ed089f5801055e9563e019df1a8d601996b'::TEXT, ARRAY[556]::BIGINT[]),
    (145::BIGINT, 'Es muy cordial y amable, flexible para ayudar al estudiante y justa con las evaluaciones, recomendada.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-07-26T00:00:00+00:00'::TIMESTAMPTZ, '490b7feaacea1e8d289ffa6e95b65fa3a76e9c980f65d5ccae4c98719b3d727b'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Explica lo necesario, no deja tareas y el trabajo es en clase. Sólo hay que hacer el ensayo y el informe técnico. No califica duro.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-07-01T00:00:00+00:00'::TIMESTAMPTZ, '5d0138c0dcf11329ab8782d4abb5da2551541114a6accc46d84ca7e854d72bd9'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Excelente profesora. Clases muy claras, con hacer todos los trabajos bien uno pasa. Se preocupa por ayudar a los estudiantes y es muy tierna.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'a9de36f4c0d6c27f97b79819ac506930e187584089088227e2ab26ead9d5d497'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Es muy fácil tener más de 90 con ella, porque no es muy exigente al calificar y nos deja hacer los trabajos en clase.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'f1f6525762b8694e1bd333af86e6ba517a35973b6075672d594230c77ec50f3d'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'La profesora muy buena gente y cariñosa. Por cierto es muy linda. Las clases son muy buenas y con solo hacer bien todos los trabajos pasa, se aprende mucho. A pesar que soy sordo me apoyó mucho y me preguntaba que sí entendió o no, me explicaba otra vez. Muy recomendado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, '075bddbbaf43126546b71f7ded5de3b67adf57c70ab02b38af0d05c26ce74f7e'::TEXT, ARRAY[556]::BIGINT[]),
    (145::BIGINT, 'Es excelente! Da tiempo en las clases para hacer los trabajos! ES LA MEJOR PROFE DE COMU ESCRITA, meta con ella y mínimo saca un 95! Es concreta con las explicaciones!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, '294be8855892a163a064532b8c19e989c625f3b8f36b7dad29e397c412c3d5b1'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Excelente profesora super recomendada, con ser responsable y cumplir las tareas se pasa. Además no es muy estricta y es muy abierta a aclarar dudas excelente como profesora y como persona'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '29c6ad213a484dc232fdcffbf58eea4af5ded47039bdc1d1565b5e592f3a30b4'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2017-06-01T00:00:00+00:00'::TIMESTAMPTZ, '3e4034bfb737e9817bf0433e42382a75a71de5c9b88473a44a5564a3bae56114'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'El curso es aburrida pero es buena profe!'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2017-05-07T00:00:00+00:00'::TIMESTAMPTZ, 'bee31c9547db7a0eae2bd6888495a12750043b5ff68f68a77505ec605ed0dc43'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'se pasa facil pero es aburrido'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'c9c3f4555090b00a3856fa57a82dd626818ac30369a086b32b0e66fd553b7b11'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'El curso en sí es aburrido pero se pasa fácil, nada más de irle a las clases siempre porque hace evaluaciones cuando uno menos se lo espera. Deja pocas exposiciones y son fáciles.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'f7023b387cbfc5f3685e76770ab802e70b453d466097afe66638ea5fa48300f9'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Como profesora es comprensiva, algo comica ,le gusta hablaaar... pero la clase se pasa rapido ,es sencillo pasar con ella y ala vez se aprende'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'dabc0296fe3e42c5e73663e7a5416dc2aec30cfd5696c5d1848fb715be63d6bd'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Muy pura vida y es fácil pasar'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-08-30T00:00:00+00:00'::TIMESTAMPTZ, '94bc853dd6261f58043e9831b7b991d91a8b066a3a63902d2a7ce1e488299458'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Desde el momento que usted matricula con ella, prácticamente ya paso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-07-01T00:00:00+00:00'::TIMESTAMPTZ, '91e7a03a7ad55e0f83d55751ba3ea527f576c6391be9adce6a3bd6fa5a05aa99'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Muy buena persona y profe. Explica muy claro y las evaluaciones son sencillas. Además, en clase generalmente da tiempo para avanzar con los trabajos y ella está ahí atendiendo las dudas de cada uno. Súper recomendada :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'cf25a340819b9947cdecb96978d403eacc63ab7aaf1a2e55fdf3d5cc6546d29c'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Excelente profe, se explica bien y uno aprende. No deja trabajos muy largos ni difíciles, muy dulce y atenta con el estudiante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '8211066b53577815841de82cb5ba342618f0cc3e3a16ba75891bc4b776855177'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-05-31T00:00:00+00:00'::TIMESTAMPTZ, 'afc89dd3ff5fd46dff2a32e9c4ee1e67f7dc2d6e30941024f947f727cb4a816b'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Excelente profe. Con ella el curso no es pesado ni aburrido. Ayuda mucho a comprender los temas. Excelente persona'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-03-19T00:00:00+00:00'::TIMESTAMPTZ, 'e38571a91beec59382810e3310df1470259606d787b44ab5e32e762ed9801350'::TEXT, ARRAY[556]::BIGINT[]),
    (145::BIGINT, 'Excelente Profesora, ericka ayuda mucho y es relajada, no presiona mucho y pregunta como van los avances de los trabajos, pero en general es perfecta, pura vida, se gana el cariño de los alumnos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2016-02-09T00:00:00+00:00'::TIMESTAMPTZ, '1a16dfb3f6349fd0014e6a128f32319deece4412dea887eaf2dc77027eb8426f'::TEXT, ARRAY[556]::BIGINT[]),
    (145::BIGINT, 'Es simplemente excelente. Super recomendada. No hace el curso pesado, aigna las evaluaciones pertinentes. Explica bien y claro. Como persona es muy agradable. Hace la clase amena, nos llevamos todos muy bien. La clase es muy conversacional y de temas interesantes. Da gusto ir a su clase'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'e0fcbebbf5d7705006c7e930c24afd1b64df50ae29daeb95dc857382049c5508'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'El curso no se vuelve muy pesado con ella. Califica suave y explica muy claro...'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-03T00:00:00+00:00'::TIMESTAMPTZ, '169b0e9071dce51823a83ddcc3eba21c743bd9b1e7941d82c479bcd717f1d6c8'::TEXT, ARRAY[600]::BIGINT[]),
    (145::BIGINT, 'Buena profe, hace que la classe valga los 2 creditos. Quita poco tiempo y es muy pura vida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'c7f0670acd44f25f9c66a2e97e44b8baf02607ebe1a5c68c19ae0c175f9489d9'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Es demasiado linda para las clases, se aprende bastante sin demasiado estrés! Y el trabajo que deja es mínimo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'eeb769544b6d976b37ad3039e132b6ed37b161dbe3ed95b7469b0e6e0578dcb3'::TEXT, ARRAY[554]::BIGINT[]),
    (145::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-14T00:00:00+00:00'::TIMESTAMPTZ, '424c75464df937bb9d20c046b8b8cc78da720821567eb84ba3de7e32f37bcd7e'::TEXT, ARRAY[554]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
